query WorkshopProjects($first: Int = 20, $after: String, $ids: [ID!], $search: String, $createdBy: [ID!], $productRevisionId: [ID!]) {
  workshopProjects(
    first: $first
    after: $after
    ids: $ids
    search: $search
    createdBy: $createdBy
    productRevisionId: $productRevisionId
  ) {
    nodes {
      id
      name
      revision
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}

query WorkshopUnits($first: Int = 20, $after: String, $ids: [ID!], $search: String, $partNumber: [String!], $mac: [String!], $status: [String!], $projectId: [ID!]) {
  workshopUnits(
    first: $first
    after: $after
    ids: $ids
    search: $search
    partNumber: $partNumber
    mac: $mac
    status: $status
    projectId: $projectId
  ) {
    nodes {
      id
      status
      revision
      updatedAt
    }
    pageInfo {
      endCursor
      hasNextPage
    }
  }
}
